  g.addColorStop(0, tone(0.78)); g.addColorStop(0.36, tone(0.32)); g.addColorStop(0.5, tone(-0.18));
  g.addColorStop(0.64, accent); g.addColorStop(0.86, tone(0.5)); g.addColorStop(1, tone(0.2));
